const KEY='cohort-payments-v1';
const today=()=>new Date().toLocaleDateString('en-CA');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(n||0);
const compact=n=>n>=100000?'₹'+(n/100000).toFixed(2)+'L':money(n);
const uid=()=>crypto.randomUUID();
const dateOffset=n=>{let d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')};
function seed(){return {version:1,settings:{name:'Cohort Coworking Spaces'},sample:true,locations:[{id:'l1',name:'HITEC City',address:'Hyderabad · Telangana'},{id:'l2',name:'Gachibowli',address:'Hyderabad · Telangana'},{id:'l3',name:'Financial District',address:'Hyderabad · Telangana'}],categories:['Rent & lease','Utilities','Internet & IT','Furniture & equipment','Maintenance','Housekeeping','Security','Marketing','Software subscriptions','Employee reimbursements','Vendor services','Construction & renovation','Interior design','Office supplies','Events','Professional services','Miscellaneous'].map((name,i)=>({id:'c'+i,name})),vendors:[{id:'v1',name:'Prestige Properties',email:'',phone:'',notes:'Commercial leasing'},{id:'v2',name:'Airtel Business',email:'',phone:'',notes:'Internet & connectivity'},{id:'v3',name:'Urban Company',email:'',phone:'',notes:'Facility maintenance'},{id:'v4',name:'Featherlite',email:'',phone:'',notes:'Office furniture'},{id:'v5',name:'TSSPDCL',email:'',phone:'',notes:'Electricity'},{id:'v6',name:'CleanPro Services',email:'',phone:'',notes:'Housekeeping'}],projects:[{id:'p1',name:'Everyday operations',budget:1500000,location:'l1'},{id:'p2',name:'Gachibowli expansion',budget:900000,location:'l2'},{id:'p3',name:'Workspace refresh',budget:450000,location:'l3'}],invoices:Array.from({length:18},(_,i)=>({id:'i'+i,number:'INV-2026-'+String(1041+i),vendor:'v'+(i%6+1),location:'l'+(i%3+1),category:['c0','c2','c4','c3','c1','c5'][i%6],project:'p'+(i%3+1),amount:[185000,24500,18200,86000,42300,32000][i%6],due:dateOffset(i<6?i*3-12:-(i-5)*12),issued:dateOffset(-20-i*10),approval:i===3?'Pending':'Approved',notes:'',document:''})),payments:Array.from({length:13},(_,j)=>{let i=j+5;return {id:'pay'+i,invoice:'i'+i,amount:[185000,24500,18200,86000,42300,32000][i%6],date:dateOffset(-(i-5)*12),method:['Bank transfer','UPI','Bank transfer'][i%3],reference:'CHT'+(80241+i),notes:''}}),history:[]}}
let db;try{const stored=localStorage.getItem(KEY);db=stored?validateBackup(JSON.parse(stored)):seed()}catch{db=seed()}
let page='dashboard',query='',locationFilter='',statusFilter='';
const navItems=[['dashboard','◫','Overview'],['invoices','▤','Invoices'],['payments','↗','Payments'],['history','◷','Payment history'],['vendors','♧','Vendors'],['locations','▦','Locations'],['categories','⊞','Expense categories'],['projects','▣','Projects / cost centers'],['reports','▥','Reports'],['settings','⚙','Settings']];
const name=(type,id)=>db[type].find(x=>x.id===id)?.name||'—';
const paid=i=>Math.round(db.payments.filter(p=>p.invoice===i.id).reduce((s,p)=>s+Math.round(p.amount*100),0))/100;
const remaining=i=>Math.max(0,Math.round((i.amount-paid(i))*100)/100);
const status=i=>remaining(i)===0?'Paid':i.due<today()?'Overdue':paid(i)>0?'Partial':'Pending';
const invoices=()=>db.invoices.filter(i=>(!locationFilter||i.location===locationFilter)&&(!statusFilter||status(i)===statusFilter)&&[i.number,name('vendors',i.vendor),name('categories',i.category),i.notes].join(' ').toLowerCase().includes(query.toLowerCase()));
function save(message){try{localStorage.setItem(KEY,JSON.stringify(db));render();if(message)toast(message);return true}catch{toast('Could not save. Browser storage is full or unavailable. Export a backup.');return false}}
function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',4500)}
function audit(text){db.history.unshift({id:uid(),date:new Date().toISOString(),text})}
function badge(s){return `<span class="badge ${s.toLowerCase()}">${esc(s)}</span>`}
function heading(title,sub,buttons=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${buttons}</div></div>`}
const addButton=(type,label)=>`<button class="primary" data-add="${type}">＋ ${label}</button>`;
function filters(statuses=true){return `<div class="toolbar"><input class="search" id="search" aria-label="Search records" placeholder="Search ${page==='dashboard'?'invoices':page}…" value="${esc(query)}"><select id="location-filter" aria-label="Filter by location"><option value="">All locations</option>${db.locations.map(l=>`<option value="${l.id}" ${locationFilter===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select>${statuses?`<select id="status-filter" aria-label="Filter by status"><option value="">All statuses</option>${['Paid','Pending','Partial','Overdue'].map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select>`:''}</div>`}
function stats(rows){let total=rows.reduce((s,i)=>s+i.amount,0),settled=rows.reduce((s,i)=>s+paid(i),0),overdue=rows.filter(i=>status(i)==='Overdue').reduce((s,i)=>s+remaining(i),0);return `<div class="stats">${[['Total expenses',total,rows.length+' invoices recorded','◈',''],['Total paid',settled,'Settled with your vendors','↗','green'],['Outstanding',total-settled,'Across open invoices','◷','orange'],['Overdue',overdue,rows.filter(i=>status(i)==='Overdue').length+' invoices need attention','!','red']].map(([l,v,d,icon,c])=>`<div class="stat"><div class="stat-label">${l}<span>${icon}</span></div><strong>${compact(v)}</strong><small class="${c}">${d}</small></div>`).join('')}</div>`}
function invoiceTable(rows,short=false){return `<div class="table-wrap"><table><thead><tr><th>Vendor / invoice</th><th>Location</th>${short?'':'<th>Category</th>'}<th>Due date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(i=>`<tr><td><div class="vendor-cell"><div class="vendor-icon">${esc(name('vendors',i.vendor).split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong>${esc(name('vendors',i.vendor))}</strong><small>${esc(i.number)}</small></div></div></td><td>${esc(name('locations',i.location))}</td>${short?'':`<td>${esc(name('categories',i.category))}</td>`}<td>${esc(i.due)}</td><td><strong>${money(i.amount)}</strong>${paid(i)&&remaining(i)?`<small>${money(remaining(i))} remaining</small>`:''}</td><td>${badge(status(i))}${i.approval==='Pending'?'<small>Awaiting approval</small>':''}</td><td><div class="row-actions"><button data-detail="${i.id}">View</button>${remaining(i)>0&&i.approval==='Approved'?`<button data-pay="${i.id}">Record payment</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No matching invoices. Try another filter or add an invoice.</td></tr>'}</tbody></table></div>`}
function spendCategories(rows){let totals=db.categories.map(c=>({...c,total:rows.filter(i=>i.category===c.id).reduce((s,i)=>s+i.amount,0)})).filter(c=>c.total).sort((a,b)=>b.total-a.total);let max=totals[0]?.total||1;return totals.slice(0,5).map((c,i)=>`<div class="category-row"><span>${esc(c.name)}</span><strong>${compact(c.total)}</strong><div class="track"><div style="width:${c.total/max*100}%;background:${['#4165ee','#6585ed','#8ba3f2','#abc0fa','#c3d0f6'][i]}"></div></div></div>`).join('')||'<div class="empty">No expenses yet</div>'}
function dashboard(){let rows=invoices(),months=Array.from({length:6},(_,i)=>{let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);let key=d.toLocaleDateString('en-CA').slice(0,7);return {label:d.toLocaleDateString('en',{month:'short'}),amount:db.payments.filter(p=>p.date.startsWith(key)&&rows.some(x=>x.id===p.invoice)).reduce((s,p)=>s+p.amount,0)}}),max=Math.max(...months.map(m=>m.amount),1);return heading('Financial overview','A clear view of your workspace expenses.',`<button data-export="invoices">↓ Export report</button><button data-import>✦ Invoice Genie</button>${addButton('invoices','New invoice')}`)+filters(false)+stats(rows)+`<div class="grid"><section class="panel chart-wrap"><div class="panel-head"><div><h2>Payment activity</h2><p>Your last six months at a glance</p></div><span class="badge">Last 6 months</span></div><div class="chart">${months.map(m=>`<div class="bar-col"><div class="bar" style="height:${m.amount/max*88}%" title="${m.label}: ${money(m.amount)}"></div><span>${m.label}</span></div>`).join('')}</div><div class="chart-key"><span class="legend-square"></span>Paid expenses · peak ${compact(max)}</div></section><section class="panel"><div class="panel-head"><div><h2>Spend by category</h2><p>Where your money goes</p></div><button class="text-btn" data-nav="reports">View report ↗</button></div>${spendCategories(rows)}</section></div><section class="panel"><div class="panel-head"><div><h2>Invoices to watch</h2><p>Upcoming and overdue payments</p></div><button class="text-btn" data-nav="invoices">All invoices →</button></div>${invoiceTable(rows.filter(i=>remaining(i)>0).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5),true)}</section><h2 class="section-title">Across your locations</h2><div class="bottom-grid">${db.locations.filter(l=>!locationFilter||l.id===locationFilter).map(l=>`<div class="location-card"><div class="eyebrow">Cohort workspace</div><h3>${esc(l.name)}</h3><div class="amount">${compact(rows.filter(i=>i.location===l.id).reduce((s,i)=>s+i.amount,0))}</div><small>Total recorded expenses</small></div>`).join('')}</div>`}
function paymentRows(){return db.payments.filter(p=>{let i=db.invoices.find(i=>i.id===p.invoice);return i&&(!locationFilter||i.location===locationFilter)&&[p.reference,p.method,name('vendors',i.vendor),i.number].join(' ').toLowerCase().includes(query.toLowerCase())}).sort((a,b)=>b.date.localeCompare(a.date))}
function payments(){return heading('Payments','Record and review vendor payments.',addButton('payments','Record payment'))+`<div class="notice">Recording a payment updates your records. It does not transfer money.</div>`+filters(false)+`<section class="panel">${paymentTable(paymentRows())}</section>`}
function paymentTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Vendor / invoice</th><th>Payment date</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${rows.map(p=>{let i=db.invoices.find(i=>i.id===p.invoice);return `<tr><td><strong>${esc(name('vendors',i?.vendor))}</strong><small>${esc(i?.number)}</small></td><td>${esc(p.date)}</td><td>${esc(p.method)}</td><td>${esc(p.reference||'—')}</td><td><strong>${money(p.amount)}</strong></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No payments found.</td></tr>'}</tbody></table></div>`}
function catalog(){let titles={locations:['Locations','Keep track of your coworking spaces.','location'],vendors:['Vendors','The people and businesses behind your spaces.','vendor'],categories:['Expense categories','Organize every kind of business expense.','category'],projects:['Projects / cost centers','Track project spending against your budget.','project']};let [t,s,singular]=titles[page],rows=db[page].filter(x=>(x.name+' '+(x.address||'')+' '+(x.notes||'')).toLowerCase().includes(query.toLowerCase()));return heading(t,s,addButton(page,'Add '+singular))+`<div class="toolbar"><input id="search" class="search" aria-label="Search ${t}" placeholder="Search ${t.toLowerCase()}…" value="${esc(query)}"></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>${page==='vendors'?'Contact':page==='locations'?'Address':page==='projects'?'Budget':'Invoices'}</th><th>Recorded expenses</th>${page==='projects'?'<th>Budget remaining</th>':''}<th></th></tr></thead><tbody>${rows.map(x=>{let field={locations:'location',vendors:'vendor',categories:'category',projects:'project'}[page],is=db.invoices.filter(i=>i[field]===x.id),sum=is.reduce((s,i)=>s+i.amount,0);return `<tr><td><strong>${esc(x.name)}</strong>${x.notes?`<small>${esc(x.notes)}</small>`:''}</td><td>${page==='vendors'?esc(x.email||x.phone||'—'):page==='locations'?esc(x.address):page==='projects'?money(x.budget):is.length}</td><td>${money(sum)}</td>${page==='projects'?`<td class="${sum>x.budget?'red':''}">${money(x.budget-sum)}</td>`:''}<td><div class="row-actions"><button data-edit="${x.id}">Edit</button><button class="danger" data-delete="${x.id}">Delete</button></div></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No records found.</td></tr>'}</tbody></table></div></section>`}
function reports(){let rows=invoices();rows=rows.filter(i=>(!reportFrom||i.issued>=reportFrom)&&(!reportTo||i.issued<=reportTo));return heading('Expense reports','Understand spending by location, category, and vendor.',`<button data-export="report">↓ Download CSV</button>`)+filters(false)+`<div class="toolbar"><label>Issued from <input type="date" id="report-from" value="${reportFrom}"></label><label>To <input type="date" id="report-to" value="${reportTo}"></label></div>`+stats(rows)+`<div class="grid"><section class="panel"><div class="panel-head"><h2>Spending by location</h2></div>${reportTable('locations','location',rows)}</section><section class="panel"><div class="panel-head"><h2>Expense breakdown</h2></div>${spendCategories(rows)}</section></div><section class="panel"><div class="panel-head"><h2>Vendor summary</h2></div>${reportTable('vendors','vendor',rows)}</section>`}
let reportFrom='',reportTo='';
function reportTable(type,field,rows){return `<div class="table-wrap"><table><thead><tr><th>${type==='vendors'?'Vendor':'Location'}</th><th>Total</th><th>Outstanding</th></tr></thead><tbody>${db[type].map(x=>{let r=rows.filter(i=>i[field]===x.id);return `<tr><td>${esc(x.name)}</td><td>${money(r.reduce((s,i)=>s+i.amount,0))}</td><td>${money(r.reduce((s,i)=>s+remaining(i),0))}</td></tr>`}).join('')}</tbody></table></div>`}
function settings(){return heading('Settings','Manage your workspace and keep a copy of your records.')+`<section class="panel settings"><section><h2>Workspace details</h2><label>Organization name<input id="org-name" value="${esc(db.settings.name)}"></label><p>Currency: Indian rupee (INR) · Dates: YYYY-MM-DD</p><button class="primary" id="save-settings">Save changes</button></section><section><h2>Backup & restore</h2><p>Records are saved only in this browser on this device. Download backups regularly. Restoring a backup replaces the current workspace.</p><div class="actions"><button id="backup">↓ Download backup</button><button id="restore">↑ Restore backup</button></div><input type="file" accept="application/json,.json" id="restore-file" hidden></section><section><h2>Sample workspace</h2><p>Explore the app with illustrative vendors and invoices, or start fresh with your own records.</p><div class="actions"><button id="reset-demo">Reload sample data</button><button class="danger" id="clear-data">Start empty workspace</button></div></section><section><h2>About this MVP</h2><p>Local record keeping for a single browser. No bank connection, user sign-in, shared database, or enforced approval permissions. Invoice approval is an internal tracking status.</p></section></section>`}
function render(){document.querySelector('#nav').innerHTML=navItems.map(([id,icon,label])=>`<a href="#${id}" class="${page===id?'active':''}"><span class="navicon">${icon}</span>${label}</a>`).join('');document.querySelector('.workspace').innerHTML=esc(db.settings.name)+'<small>Finance workspace</small>';document.querySelector('#crumb').textContent=navItems.find(x=>x[0]===page)?.[2]||'Overview';document.querySelector('.demo').textContent=db.sample?'Sample data':'Local data';document.querySelector('#today').textContent=new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});document.querySelector('#app').innerHTML=page==='dashboard'?dashboard():page==='invoices'?heading('Invoices','Manage invoices from receipt to settlement.',`<button data-import>✦ Invoice Genie</button>`+addButton('invoices','New invoice'))+filters()+`<section class="panel">${invoiceTable(invoices())}</section>`:page==='payments'?payments():page==='history'?heading('Payment history','Your payment ledger and workspace activity.',`<button data-export="payments">↓ Export payments</button>`)+filters(false)+`<section class="panel">${paymentTable(paymentRows())}</section><h2 class="section-title">Recent activity</h2><section class="panel">${db.history.slice(0,30).map(h=>`<div class="category-row"><span>${esc(h.text)}</span><small>${esc(new Date(h.date).toLocaleString())}</small></div>`).join('')||'<div class="empty">New changes will appear here.</div>'}</section>`:page==='reports'?reports():page==='settings'?settings():catalog();bind()}
function route(){page=location.hash.slice(1)||'dashboard';if(!navItems.some(x=>x[0]===page))page='dashboard';query='';locationFilter='';statusFilter='';document.body.classList.remove('menu-open');render()}
function rerenderInput(e,key){let pos=e.target.selectionStart;if(key==='q')query=e.target.value;render();let el=document.querySelector('#search');if(key==='q'){el.focus();el.setSelectionRange(pos,pos)}}
function bind(){document.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>window.openInvoiceImport?.());document.querySelector('#search')?.addEventListener('input',e=>rerenderInput(e,'q'));document.querySelector('#location-filter')?.addEventListener('change',e=>{locationFilter=e.target.value;render()});document.querySelector('#status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;render()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>openForm('payments',null,b.dataset.pay));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openForm('invoices',b.dataset.detail));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>location.hash=b.dataset.nav);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(page,b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeRecord(page,b.dataset.delete));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportCSV(b.dataset.export));document.querySelector('#report-from')?.addEventListener('change',e=>{reportFrom=e.target.value;render()});document.querySelector('#report-to')?.addEventListener('change',e=>{reportTo=e.target.value;render()});document.querySelector('#save-settings')?.addEventListener('click',()=>{let n=document.querySelector('#org-name').value.trim();if(!n)return toast('Enter an organization name.');db.settings.name=n;save('Workspace updated')});document.querySelector('#backup')?.addEventListener('click',()=>download(JSON.stringify(db,null,2),'cohort-backup-'+today()+'.json','application/json'));document.querySelector('#restore')?.addEventListener('click',()=>document.querySelector('#restore-file').click());document.querySelector('#restore-file')?.addEventListener('change',restore);document.querySelector('#reset-demo')?.addEventListener('click',()=>{if(confirm('Replace all current records with sample data? Download a backup first.')){db=seed();save('Sample workspace restored')}});document.querySelector('#clear-data')?.addEventListener('click',()=>{if(confirm('Delete all invoices, payments, vendors, locations, projects and history from this browser? Download a backup first.')){let settings=db.settings;db=seed();for(let k of ['invoices','payments','vendors','locations','projects','history'])db[k]=[];db.settings=settings;db.sample=false;save('Your empty workspace is ready')}})}
function input(label,key,value='',type='text',required=true,extra=''){return `<label ${type==='textarea'?'class="wide"':''}>${label}${type==='textarea'?`<textarea name="${key}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}>`}</label>`}
function select(label,key,options,value='',optional=false){return `<label>${label}<select name="${key}" ${optional?'':'required'}>${optional?'<option value="">None</option>':'<option value="">Select…</option>'}${options.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`}
function openForm(type,id=null,invoiceId=''){let item=db[type]?.find(x=>x.id===id)||{},fields='';document.querySelector('#dialog-title').textContent=(id?'Edit ':'New ')+({invoices:'invoice',payments:'payment',locations:'location',vendors:'vendor',categories:'expense category',projects:'project / cost center'}[type]);if(type==='invoices'){if(!db.vendors.length||!db.locations.length)return toast('Add a vendor and location before creating an invoice.');fields=input('Invoice number','number',item.number||'INV-'+Date.now().toString().slice(-6))+input('Amount (INR)','amount',item.amount||'','number',true,'min="0.01" step="0.01"')+select('Vendor','vendor',db.vendors,item.vendor)+select('Location','location',db.locations,item.location)+select('Expense category','category',db.categories,item.category)+select('Project / cost center','project',db.projects,item.project,true)+input('Issue date','issued',item.issued||today(),'date')+input('Due date','due',item.due||today(),'date')+select('Approval','approval',[{id:'Pending',name:'Pending'},{id:'Approved',name:'Approved'}],item.approval||'Approved')+input('Document link','document',item.document||'','url',false)+input('Notes','notes',item.notes||'','textarea',false);if(item.sourceFilename)fields+=`<p class="wide">Imported from: ${esc(item.sourceFilename)} · reviewed on import</p>`;if(id)fields+=`<p class="wide">Paid: ${money(paid(item))} · Outstanding: ${money(remaining(item))}</p>`}else if(type==='payments'){let eligible=db.invoices.filter(i=>remaining(i)>0&&i.approval==='Approved');if(!eligible.length)return toast('No approved unpaid invoices. Add or approve an invoice first.');let chosen=eligible.find(i=>i.id===invoiceId)||eligible[0];fields=select('Invoice','invoice',eligible.map(i=>({id:i.id,name:i.number+' · '+name('vendors',i.vendor)+' · '+money(remaining(i))})),chosen.id)+input('Amount (INR)','amount',remaining(chosen),'number',true,'min="0.01" step="0.01"')+input('Payment date','date',today(),'date',true,`max="${today()}"`)+select('Payment method','method',['Bank transfer','UPI','Card','Cash','Cheque','Other'].map(s=>({id:s,name:s})),'Bank transfer')+input('Reference number','reference','','text',false)+input('Notes','notes','','textarea',false)}else{fields=input('Name','name',item.name||'');if(type==='locations')fields+=input('Address','address',item.address||'','text',false);if(type==='vendors')fields+=input('Email','email',item.email||'','email',false)+input('Phone','phone',item.phone||'','tel',false)+input('Notes','notes',item.notes||'','textarea',false);if(type==='projects')fields+=input('Budget (INR)','budget',item.budget||'','number',true,'min="0" step="0.01"')+select('Location','location',db.locations,item.location,true)}document.querySelector('#fields').innerHTML=fields;document.querySelector('#form-error').textContent='';document.querySelector('#form').onsubmit=e=>{e.preventDefault();try{let data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=data[k].trim());if(type==='invoices'){data.amount=Math.round(Number(data.amount)*100)/100;if(!Number.isFinite(data.amount)||data.amount<=0)throw Error('Enter a valid positive amount.');if(data.amount<paid(item))throw Error('Invoice amount cannot be less than payments already recorded.');if(data.due<data.issued)throw Error('Due date must be on or after the issue date.');if(db.invoices.some(i=>i.id!==id&&i.vendor===data.vendor&&i.number.toLowerCase()===data.number.toLowerCase()))throw Error('This vendor already has an invoice with that number.');if(paid(item)>0&&data.approval!=='Approved')throw Error('An invoice with recorded payments must remain approved.')}if(type==='payments'){data.amount=Math.round(Number(data.amount)*100)/100;let inv=db.invoices.find(i=>i.id===data.invoice);if(!inv||inv.approval!=='Approved'||!Number.isFinite(data.amount)||data.amount<=0||data.amount>remaining(inv)+.001)throw Error('Payment must be positive and no greater than the approved invoice balance.');if(data.date>today())throw Error('Payment date cannot be in the future.')}if(type==='projects'){data.budget=Number(data.budget);if(!Number.isFinite(data.budget)||data.budget<0)throw Error('Enter a valid nonnegative budget.');}if('name' in data&&!data.name)throw Error('Enter a name.');if(type==='invoices'&&!data.number)throw Error('Enter an invoice number.');if(data.name&&db[type].some(x=>x.id!==id&&x.name.toLowerCase()===data.name.toLowerCase()))throw Error('A record with this name already exists.');if(id)Object.assign(item,data);else db[type].push({id:uid(),...data});audit(`${id?'Updated':'Added'} ${type==='payments'?'payment of '+money(data.amount):data.name||data.number}`);save('Record saved');document.querySelector('#dialog').close()}catch(err){document.querySelector('#form-error').textContent=err.message}};document.querySelector('#dialog').showModal();if(type==='payments')document.querySelector('[name="invoice"]').onchange=e=>{document.querySelector('[name="amount"]').value=remaining(db.invoices.find(i=>i.id===e.target.value))}}
function removeRecord(type,id){let field={locations:'location',vendors:'vendor',categories:'category',projects:'project'}[type];if(db.invoices.some(i=>i[field]===id)||(type==='locations'&&db.projects.some(p=>p.location===id)))return toast('This record is in use. Update linked records before deleting.');let item=db[type].find(x=>x.id===id);if(confirm('Delete '+item.name+'?')){db[type]=db[type].filter(x=>x.id!==id);audit('Deleted '+item.name);save('Record deleted')}}
function download(data,filename,mime){let url=URL.createObjectURL(new Blob([data],{type:mime})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(type){let rows,headers;if(type==='payments'){headers=['Vendor','Invoice','Date','Method','Reference','Amount'];rows=paymentRows().map(p=>{let i=db.invoices.find(i=>i.id===p.invoice);return [name('vendors',i.vendor),i.number,p.date,p.method,p.reference,p.amount]})}else{headers=['Invoice','Vendor','Location','Category','Project','Issued','Due','Amount','Paid','Outstanding','Status','Approval'];rows=invoices().filter(i=>type!=='report'||(!reportFrom||i.issued>=reportFrom)&&(!reportTo||i.issued<=reportTo)).map(i=>[i.number,name('vendors',i.vendor),name('locations',i.location),name('categories',i.category),name('projects',i.project),i.issued,i.due,i.amount,paid(i),remaining(i),status(i),i.approval])}let cell=s=>'"'+String(s??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('\uFEFF'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'cohort-'+type+'-'+today()+'.csv','text/csv;charset=utf-8');toast('Export downloaded')}
function validateBackup(d){if(d?.version!==1||typeof d.settings?.name!=='string')throw Error('Unsupported backup format.');for(let key of ['locations','vendors','categories','projects','invoices','payments','history']){if(!Array.isArray(d[key])||d[key].some(x=>!x||typeof x.id!=='string')||new Set(d[key].map(x=>x.id)).size!==d[key].length)throw Error('Invalid '+key+' records.')}for(let k of ['locations','vendors','categories','projects'])if(d[k].some(x=>typeof x.name!=='string'))throw Error('Invalid names.');let has=(k,id)=>d[k].some(x=>x.id===id);for(let p of d.projects)if(!Number.isFinite(p.budget)||p.budget<0||(p.location&&!has('locations',p.location)))throw Error('Invalid project.');for(let i of d.invoices){if(!has('vendors',i.vendor)||!has('locations',i.location)||!has('categories',i.category)||(i.project&&!has('projects',i.project))||!Number.isFinite(i.amount)||i.amount<=0||!/^\d{4}-\d{2}-\d{2}$/.test(i.due)||!/^\d{4}-\d{2}-\d{2}$/.test(i.issued)||typeof i.number!=='string'||!['Approved','Pending'].includes(i.approval))throw Error('Invalid invoice or missing linked record.')}for(let p of d.payments){if(!has('invoices',p.invoice)||!Number.isFinite(p.amount)||p.amount<=0||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||typeof p.method!=='string')throw Error('Invalid payment.')}for(let i of d.invoices)if(d.payments.filter(p=>p.invoice===i.id).reduce((s,p)=>s+p.amount,0)>i.amount+.001||(d.payments.some(p=>p.invoice===i.id)&&i.approval!=='Approved'))throw Error('Backup contains overpaid invoices.');return d}
async function restore(e){let f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error('Backup is too large (maximum 5 MB).');let next=validateBackup(JSON.parse(await f.text()));if(confirm('Replace the current workspace with this backup?')){db=next;save('Backup restored')}}catch(err){toast('Restore failed: '+err.message)}}
window.addEventListener('hashchange',route);document.querySelector('#close').onclick=document.querySelector('#cancel').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#menu').onclick=()=>document.body.classList.toggle('menu-open');
function savedBreakdown(invoice){const currency=invoice.currency||'INR',items=invoice.lineItems||[],parts=items.map(item=>`${item.quantity} × ${item.description}: ${currency} ${item.total} (${currency} ${item.unitPrice} each)`),summary=invoice.breakdown||{};if(!items.length)return `No stored line-item breakdown is available for invoice ${invoice.number}.`;if(summary.subtotal!==null&&summary.subtotal!==undefined)parts.push(`Subtotal: ${currency} ${summary.subtotal}`);if(summary.tax!==null&&summary.tax!==undefined)parts.push(`Tax: ${currency} ${summary.tax}`);if(summary.shipping!==null&&summary.shipping!==undefined)parts.push(`Shipping & handling: ${currency} ${summary.shipping}`);parts.push(`Total: ${currency} ${summary.total??invoice.amount}`);return parts.join('\n')}
function answerSavedInvoice(value){const lower=value.trim().toLowerCase();if(!lower)return '';const invoice=db.invoices.find(i=>lower.includes(i.number.toLowerCase())),vendor=db.vendors.find(v=>lower.includes(v.name.toLowerCase()));
  if(invoice){const words=lower.split(/[^a-z0-9]+/).filter(word=>word.length>2&&!['what','which','price','cost','show','invoice','breakdown'].includes(word)),item=(invoice.lineItems||[]).find(row=>words.some(word=>row.description.toLowerCase().includes(word)));if(/breakdown|line\s*items?|itemized/.test(lower))return savedBreakdown(invoice);if(item&&/price|cost|amount|desk|meeting|print|scan|membership/.test(lower))return `${item.quantity} × ${item.description}: ${invoice.currency||'INR'} ${item.total} total at ${invoice.currency||'INR'} ${item.unitPrice} each.`;return `Invoice ${invoice.number}: vendor ${name('vendors',invoice.vendor)}, amount ${invoice.currency&&invoice.currency!=='INR'?invoice.currency+' '+invoice.amount:money(invoice.amount)}, issued ${invoice.issued}, due ${invoice.due}, location ${name('locations',invoice.location)}, category ${name('categories',invoice.category)}, status ${status(invoice)}, approval ${invoice.approval}.`}
  if(vendor){const rows=db.invoices.filter(i=>i.vendor===vendor.id),total=rows.reduce((sum,i)=>sum+i.amount,0);return `${vendor.name} has ${rows.length} saved invoice${rows.length===1?'':'s'} totaling ${money(total)}. ${rows.slice(0,5).map(i=>i.number+' ('+status(i)+')').join(', ')||'No invoices found.'}`}
  if(/overdue/.test(lower)){const rows=db.invoices.filter(i=>status(i)==='Overdue');return rows.length?`${rows.length} overdue invoice${rows.length===1?'':'s'}: ${rows.slice(0,8).map(i=>i.number+' · '+name('vendors',i.vendor)+' · '+money(remaining(i))).join('; ')}.`:'There are no overdue invoices.'}
  if(/pending|unpaid|outstanding/.test(lower)){const rows=db.invoices.filter(i=>remaining(i)>0);return `${rows.length} invoices have an outstanding balance totaling ${money(rows.reduce((sum,i)=>sum+remaining(i),0))}.`}
  if(/summary|total|how many/.test(lower))return `There are ${db.invoices.length} saved invoices totaling ${money(db.invoices.reduce((sum,i)=>sum+i.amount,0))}. Paid: ${money(db.payments.reduce((sum,p)=>sum+p.amount,0))}. Outstanding: ${money(db.invoices.reduce((sum,i)=>sum+remaining(i),0))}.`;
  if(/fill|change|update|edit|save|delete/.test(lower))return 'I am read-only. I can search and answer questions, but I never change your records.';
  return 'I could not find that invoice. Include the full invoice number, then ask for its details or price breakdown. You can also ask about a vendor, overdue invoices, outstanding balances, or a workspace summary.'}
function mountDashboardGenie(){const stats=document.querySelector('#app .stats');if(!stats||document.querySelector('#dashboard-genie'))return;stats.insertAdjacentHTML('afterend',`<section id="dashboard-genie" class="dashboard-genie"><div class="dashboard-genie-info"><span class="genie-mini-orb">✦</span><div><h2>Invoice Genie</h2><p>Search saved invoices and ask about vendors, totals, dates, status, or stored price breakdowns. Genie only reads your local records.</p><div class="genie-quick"><button type="button" data-dashboard-genie="Show overdue invoices">Overdue invoices</button><button type="button" data-dashboard-genie="Give me an invoice summary">Workspace summary</button></div></div></div><div class="dashboard-genie-chat"><div id="dashboard-genie-messages" class="genie-messages" aria-live="polite"><div class="genie-bubble bot">Try “Show invoice INV-2026-1041” or “Price breakdown for invoice 1234.”</div></div><form id="dashboard-genie-form"><input id="dashboard-genie-question" aria-label="Ask Invoice Genie" placeholder="Ask about a saved invoice…" autocomplete="off"><button class="primary" aria-label="Send to Genie">↑</button></form></div></section>`);const messages=document.querySelector('#dashboard-genie-messages'),question=document.querySelector('#dashboard-genie-question'),ask=value=>{const q=value.trim();if(!q)return;for(const [message,kind] of [[q,'user'],[answerSavedInvoice(q),'bot']]){const bubble=document.createElement('div');bubble.className='genie-bubble '+kind;bubble.textContent=message;messages.append(bubble)}messages.scrollTop=messages.scrollHeight};document.querySelectorAll('[data-dashboard-genie]').forEach(button=>button.onclick=()=>ask(button.dataset.dashboardGenie));document.querySelector('#dashboard-genie-form').onsubmit=e=>{e.preventDefault();ask(question.value);question.value=''}}
const renderWithoutDashboardGenie=render;render=function(){renderWithoutDashboardGenie();if(page==='dashboard'&&typeof document.createElement==='function')mountDashboardGenie()};route();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_cohort_summary',description:'Read expense totals from this local workspace.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({invoices:db.invoices.length,total:db.invoices.reduce((s,i)=>s+i.amount,0),paid:db.payments.reduce((s,p)=>s+p.amount,0)})});document.modelContext.registerTool({name:'start_invoice_creation',description:'Open the new invoice form; this does not save an invoice.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{openForm('invoices');return {opened:document.querySelector('#dialog').open}}})}catch{}}
